function readSettings(){try{const x={...DEFAULTS,...JSON.parse(localStorage.getItem(KEY)||"{}")};if(!["auto","day","night"].includes(x.appearance))x.appearance="auto";if(!["mav","vscode"].includes(x.logColorScheme))x.logColorScheme="mav";if(!["auto","compat","balanced","quality"].includes(x.aiModelTier))x.aiModelTier="auto";return x;}catch(_){return {...DEFAULTS};}}
function save(){try{localStorage.setItem(KEY,JSON.stringify(settings));}catch(_){}applyTheme();renderSettings();}
function resolvedTheme(){if(settings.appearance!=="auto")return settings.appearance;const h=new Date().getHours();return h>=7&&h<19?"day":"night";}
