function refreshAssistantContext(){const root=$("#mfe-assistant-context");if(root)root.innerHTML=assistantContextHtml();}

function renderChat(){
 const root=$("#mfe-chat-messages");if(!root)return;refreshAssistantContext();
 if(!ai.messages.length){root.innerHTML=`<div class="mfe-welcome"><div class="mfe-welcome-icon">✦</div><div><strong>Ask me what the field technician should do next.</strong><p>I’ll correlate the live Farm state, alerts, codec reservations, NVX evidence, routes, and recent logs already visible in this monitor.</p></div></div><div class="mfe-welcome-rules"><span>Read only</span><span>Evidence grounded</span><span>Local model optional</span></div>`;return;}
 root.innerHTML=ai.messages.map((m,index)=>{
   if(m.role==="user")return `<article class="mfe-message user has-copy"><button type="button" class="mfe-copy-button" data-mfe-copy="${index}" aria-label="Copy message"><span class="mfe-copy-icon"></span></button><span class="who">You</span><div class="answer">${escapeHtml(m.text||"")}</div><div class="micro">${m.time?escapeHtml(m.time):""}</div></article>`;
   const trace=m.interpretation?interpretationTraceHtml(m.interpretation,false):"";
   const evidence=m.evidence?.length?`<details class="mfe-evidence"><summary><span>Evidence used</span><b>${m.evidence.length}</b></summary><div class="mfe-evidence-list">${m.evidence.map(e=>`<div class="mfe-evidence-item"><span>${escapeHtml(String(e.kind||"evidence").toUpperCase())}</span><div>${escapeHtml(String(e.id||""))}${e.id?" · ":""}${escapeHtml(String(e.text||""))}</div></div>`).join("")}</div>${m.parser?`<div class="mfe-evidence-meta">Request interpretation: ${escapeHtml(m.parser)}</div>`:""}</details>`:"";
   return `<article class="mfe-message assistant has-copy"><button type="button" class="mfe-copy-button" data-mfe-copy="${index}" aria-label="Copy message"><span class="mfe-copy-icon"></span></button><div class="mfe-assistant-answer-head"><span class="who">MAV VTC Farm Advisor</span>${sourceBadgeHtml(m)}</div>${m.tag?`<div class="mfe-answer-title">${escapeHtml(m.tag)}</div>`:""}<div class="answer">${escapeHtml(m.text||"")}</div><div class="mfe-answer-support">${evidence}${trace}</div><div class="micro">${escapeHtml(m.source||"MAV Knowledge")}${m.time?" · "+escapeHtml(m.time):""}</div></article>`;
 }).join("");
 root.querySelectorAll("[data-mfe-copy]").forEach(button=>button.onclick=()=>{const message=ai.messages[Number(button.dataset.mfeCopy)];if(message)copyChatText(message.text,button);});root.scrollTop=root.scrollHeight;
}
function progress(value,stage){ai.progress=Math.max(0,Math.min(100,Number(value)||0));const wrap=$("#mfe-ai-progress");if(!wrap)return;wrap.hidden=value<=0;$("#mfe-ai-progress-bar").style.width=ai.progress+"%";$("#mfe-ai-progress-pct").textContent=Math.round(ai.progress)+"%";$("#mfe-ai-progress-stage").textContent=stage||"Working…";}
async function withTimeout(promise,timeoutMs,label){let timer;const timeout=new Promise((_,reject)=>{timer=setTimeout(()=>{const e=new Error(`${label||"Operation"} timed out after ${Math.round(timeoutMs/1000)}s`);e.name="MAVTimeoutError";reject(e);},timeoutMs);});return Promise.race([Promise.resolve(promise),timeout]).finally(()=>clearTimeout(timer));}
async function modelPack(model){const c=new AbortController(),t=setTimeout(()=>c.abort(),3500);try{return await fetch(MODEL_ROOT+model.id+"/config.json",{cache:"no-store",signal:c.signal}).then(r=>r.ok).catch(()=>false);}finally{clearTimeout(t);}}
async function selectModel(){if(settings.aiModelTier!=="auto"){const m=MODELS[settings.aiModelTier];if(m.device==="webgpu"&&!navigator.gpu)throw new Error(m.label+" requires WebGPU.");if(!await modelPack(m))throw new Error(m.label+" is not installed under /ai/models.");return m;}const available={};for(const k of ["quality","balanced","compat"])available[k]=await modelPack(MODELS[k]);const cores=Number(navigator.hardwareConcurrency||0),mem=Number(navigator.deviceMemory||0);if(available.quality&&navigator.gpu&&cores>=8&&(!mem||mem>=8))return MODELS.quality;if(available.balanced&&cores>=4&&(!mem||mem>=4))return MODELS.balanced;if(available.compat)return MODELS.compat;if(available.balanced)return MODELS.balanced;if(available.quality&&navigator.gpu)return MODELS.quality;throw new Error("No compatible local model pack is installed under /ai/models.");}
async function loadModel(){const desired=await withTimeout(selectModel(),7000,"Local model selection");if(ai.generator&&ai.selected?.id===desired.id)return ai.generator;if(ai.loadPromise)return ai.loadPromise;if(ai.generator){try{await Promise.race([Promise.resolve(ai.generator.dispose?.()),new Promise(r=>setTimeout(r,1200))]);}catch(_){}ai.generator=null;}status("Loading "+desired.label+"…");progress(18,"Loading local AI runtime…");ai.loadPromise=(async()=>{try{const module=await withTimeout(import(MODEL_RUNTIME),7000,"Local AI runtime load"),{env,pipeline}=module;env.allowLocalModels=true;env.allowRemoteModels=false;env.localModelPath=MODEL_ROOT;env.backends.onnx.wasm.wasmPaths={mjs:new URL("/ai/vendor/ort-wasm-simd-threaded.jsep.js",location.href).href,wasm:new URL("/ai/vendor/ort-wasm-simd-threaded.jsep.wasm",location.href).href};env.backends.onnx.wasm.numThreads=1;env.backends.onnx.wasm.proxy=true;const generator=await withTimeout(pipeline("text-generation",desired.id,{dtype:desired.dtype,...(desired.device?{device:desired.device}:{}),progress_callback:p=>{if(p&&p.status==="progress"&&p.total){const pc=Math.max(0,Math.min(100,p.loaded/p.total*100));status("Loading "+desired.label+" · "+Math.round(pc)+"%");progress(24+pc*.5,"Loading "+desired.short+" · "+Math.round(pc)+"%");}}}),45000,"Local model initialization");ai.generator=generator;ai.selected=desired;status("Local model ready · "+desired.short);progress(78,"Local model ready · "+desired.short);return generator;}catch(error){status("Knowledge mode · "+String(error.message||error));throw error;}finally{ai.loadPromise=null;}})();return ai.loadPromise;}
function evidenceRecords(){
 const records=[];const put=(kind,id,text)=>{text=compactText(text,1800);if(text)records.push({kind,id:String(id||records.length+1),text});};
 const health=$("#overview-health")?.textContent,healthDetail=$("#overview-health-detail")?.textContent,cws=$("#overview-cws")?.textContent,cwsDetail=$("#overview-cws-detail")?.textContent,topology=$("#overview-dsp")?.textContent,topologyDetail=$("#overview-dsp-detail")?.textContent,config=$("#overview-config")?.textContent,configDetail=$("#overview-config-detail")?.textContent;
 put("health","monitor",`${health||"Unknown"}. ${healthDetail||""}`);put("cws","vtcfarm",`${cws||"Unknown"}. ${cwsDetail||""}`);put("topology","farm",`${topology||"Unknown"}. ${topologyDetail||""}`);put("configuration","definition",`${config||"Unknown"}. ${configDetail||""}`);
 $$(".alert-card").forEach((card,i)=>{const sev=compactText(card.querySelector(".alert-severity")?.textContent,80),device=compactText(card.querySelector(".alert-device")?.textContent,160),title=compactText(card.querySelector("h3")?.textContent,240),detail=compactText(card.querySelector(".alert-content p")?.textContent,600),stateText=compactText(card.querySelector(".alert-state")?.textContent,80);put("alert",device||String(i+1),`${sev} ${device}: ${title}. ${detail} State=${stateText}`);});
 $$(".device-card").forEach((card,i)=>{const name=compactText(card.querySelector("h3")?.textContent,220),category=compactText(card.querySelector(".device-category")?.textContent,100),statusText=compactText(card.querySelector(".health-mini")?.textContent,120),summary=compactText(card.querySelector(".device-card-summary")?.textContent,800);put("device",name||String(i+1),`${category} ${name}. ${statusText}. ${summary}`);});
 $$(".route-item").forEach((item,i)=>put("route",String(i+1),item.textContent));
 $$(".log-row").slice(0,20).forEach((row,i)=>put("log",String(i+1),row.textContent));
 if($("[data-view='commands']")){put("commands","farm","Farm command UI exposes reserve, release, re-route streams, dial, hang up, answer, DTMF, presentation on/off, self view on/off, and NVX video source-to-destination routing when the corresponding CWS capability is available.");}
 return records;
}
function deviceNames(){return $$(".device-card h3").map(x=>String(x.textContent||"").trim()).filter(Boolean);}
function resolveTarget(question){const q=normalizeText(question);let best="",score=0;for(const name of deviceNames()){const n=normalizeText(name);if(!n)continue;let s=0;if(q.includes(n))s=100+n.length;else{const words=n.split(" ").filter(x=>x.length>2),hits=words.filter(w=>q.includes(w)).length;if(hits>=2)s=20+hits*10;}if(s>score){score=s;best=name;}}return best;}

function isFarmRegressionRequest(question){
 const q=normalizeText(question);
 return /\b(run|perform|execute|start)\b.*\b(regression|regression test|regression tests|test suite)\b/.test(q)
   || /\b(regression|regression test|regression tests)\b.*\b(run|test|check)\b/.test(q);
}
async function runVtcFarmRegression(){
 status("Running VTC Farm regression tests…");progress(20,"Invoking Farm-native regression suite…");
 const response=await farmCws("/system/vtcfarm/regression","POST",{});
 const value=farmValue(response)||{},checks=arr(value.Checks||value.checks);
 const pass=Number(value.Pass??value.pass??0),fail=Number(value.Fail??value.fail??0),warn=Number(value.Warn??value.warn??0);
 progress(100,"VTC Farm regression complete");status(`Regression complete · ${pass} PASS · ${fail} FAIL · ${warn} WARN`);
 return {text:`VTC Farm regression finished: ${pass} passed, ${fail} failed, ${warn} warned.`,tag:`${pass} PASS · ${fail} FAIL · ${warn} WARN`,source:"VTC Farm native regression",evidence:checks.map((x,i)=>({kind:"test",id:`#${i+1}`,text:`[${x.Status||x.status}] ${x.Name||x.name}: ${x.Detail||x.detail}`})),results:checks};
}

function classifyIntent(question){const q=normalizeText(question);if(/\b(regression|regression test|regression tests|test suite)\b/.test(q))return "regression";if(/\b(command|commands|control|controls|what can i do|available cws)\b/.test(q))return "commands";if(/\b(field|check first|what should i check|diagnose first|troubleshoot first)\b/.test(q))return "field_check";if(/\b(alert|alerts|warning|warnings|error|errors|issue|issues)\b/.test(q))return "alerts";if(/\b(route|routing|stream|streams|rtsp|signal path)\b/.test(q))return "routes";if(/\b(inventory|configured devices|device inventory|how many|encoder|decoder|nvx)\b/.test(q))return "inventory";if(/\b(health|healthy|status|online|responding|cws)\b/.test(q))return resolveTarget(question)?"device_status":"health";if(resolveTarget(question))return "device_status";return "general";}
