  if(typeof window.showSaveFilePicker==="function"){try{const handle=await window.showSaveFilePicker({suggestedName:filename,types:[{description:"MAV VTC Farm HTML chat log",accept:{"text/html":[".html"]}}]});const writable=await handle.createWritable();await writable.write(blob);await writable.close();if(status)status.textContent="Saved locally. No cloud copy was created.";setTimeout(farmCloseChatExport,700);return;}catch(error){if(error?.name==="AbortError"){if(status)status.textContent="Save canceled. No file was created.";return;}}}
